<section class="page-hero page-hero-compact"><div class="shell page-hero-grid"><div><span class="mono-label">USER ACCOUNTS / FORM</span><h1><?= esc($heading) ?></h1></div><p>Enter the staff details below. Usernames must be unique.</p></div></section>
<section class="section form-section"><div class="shell form-shell"><form class="account-form" method="post" action="<?= site_url($action) ?>" enctype="multipart/form-data"><div class="form-heading"><span class="mono-label">USER DETAILS</span><h2>Account information</h2></div><?= csrf_field() ?><?= validation_list_errors() ?><label for="username">Username <span>*</span></label><input id="username" name="username" type="text" value="<?= esc(old('username', $user['username'] ?? '')) ?>" required minlength="3" maxlength="50"><label for="full_name">Full name <span>*</span></label><input id="full_name" name="full_name" type="text" value="<?= esc(old('full_name', $user['full_name'] ?? '')) ?>" required maxlength="100"><?php if (! empty($user)): ?><label for="avatar">Profile picture</label><input id="avatar" name="avatar" type="file" accept="image/jpeg,image/png"><small class="form-help">JPG or PNG only, maximum 2MB. The image is resized to a square thumbnail.</small><?php endif; ?><div class="form-actions"><a class="text-link" href="<?= site_url('users') ?>">Cancel</a><button class="button button-primary" type="submit">Save user <span aria-hidden="true">&#8594;</span></button></div></form></div></section>
